class Solution {

    /**
     * @param Integer $n
     * @return Integer
     */
    function minSteps($n) {
        $result = 0;
        $d = 2;
        while ($n > 1) {
            while ($n % $d == 0) {
                $result += $d;
                $n = intdiv($n, $d);
            }
            $d++;
        }
        return $result;
    }
}
