```php
class Solution {

    /**
     * @param Integer[] $arr
     * @return Integer
     */
    function numFactoredBinaryTrees($arr) {
        $MOD = 1000000007;
        sort($arr);
        $n = count($arr);
        $dp = [];
        $total = 0;
        for ($i = 0; $i < $n; $i++) {
            $v = $arr[$i];
            $count = 1;
            for ($j = 0; $j < $i; $j++) {
                $a = $arr[$j];
                if ($a * $a > $v) break;
                if ($v % $a == 0) {
                    $b = intdiv($v, $a);
                    if (isset($dp[$b])) {
                        if ($a == $b) {
                            $count = ($count + $dp[$a] * $dp[$b]) % $MOD;
                        } else {
                            $count = ($count + 2 * (($dp[$a] * $dp[$b]) % $MOD)) % $MOD;
                        }
                    }
                }
            }
            $dp[$v] = $count;
            $total = ($total + $count) % $MOD;
        }
        return $total;
    }
}
