class Solution {

    /**
     * @param Integer[][] $grid
     * @param Integer[][] $hits
     * @return Integer[]
     */
    function hitBricks($grid, $hits) {
        $m = count($grid);
        $n = count($grid[0]);
        $roof = $m * $n;
        $parent = range(0, $roof);
        $size = array_fill(0, $roof + 1, 1);

        $find = function($x) use (&$parent) {
            while ($parent[$x] != $x) {
                $parent[$x] = $parent[$parent[$x]];
                $x = $parent[$x];
            }
            return $x;
        };
        $union = function($a, $b) use (&$parent, &$size, $find) {
            $ra = $find($a);
            $rb = $find($b);
            if ($ra == $rb) return;
            if ($size[$ra] < $size[$rb]) { $t = $ra; $ra = $rb; $rb = $t; }
            $parent[$rb] = $ra;
            $size[$ra] += $size[$rb];
        };

        $g = $grid;
        foreach ($hits as $h) {
            $g[$h[0]][$h[1]] = 0;
        }

        $dirs = [[1,0],[-1,0],[0,1],[0,-1]];
        for ($i = 0; $i < $m; $i++) {
            for ($j = 0; $j < $n; $j++) {
                if ($g[$i][$j] == 1) {
                    $id = $i * $n + $j;
                    if ($i == 0) $union($id, $roof);
                    if ($i > 0 && $g[$i-1][$j] == 1) $union($id, ($i-1) * $n + $j);
                    if ($j > 0 && $g[$i][$j-1] == 1) $union($id, $i * $n + $j - 1);
                }
            }
        }

        $k = count($hits);
        $res = array_fill(0, $k, 0);
        for ($t = $k - 1; $t >= 0; $t--) {
            $r = $hits[$t][0];
            $c = $hits[$t][1];
            if ($grid[$r][$c] == 0) {
                $res[$t] = 0;
                continue;
            }
            $before = $size[$find($roof)];
            $g[$r][$c] = 1;
            $id = $r * $n + $c;
            if ($r == 0) $union($id, $roof);
            foreach ($dirs as $d) {
                $nr = $r + $d[0];
                $nc = $c + $d[1];
                if ($nr >= 0 && $nr < $m && $nc >= 0 && $nc < $n && $g[$nr][$nc] == 1) {
                    $union($id, $nr * $n + $nc);
                }
            }
            $after = $size[$find($roof)];
            $res[$t] = max(0, $after - $before - 1);
        }
        return $res;
    }
}
