    function kLengthApart($nums, $k) {
        $last = -1;
        $n = count($nums);
        for ($i = 0; $i < $n; $i++) {
            if ($nums[$i] == 1) {
                if ($last >= 0 && $i - $last - 1 < $k) {
                    return false;
