     * @param String[] $words
     * @return Integer[]
     */
    function numSmallerByFrequency($queries, $words) {
        $f = function($s) {
            $n = strlen($s);
            $min = null;
            $cnt = 0;
            for ($i = 0; $i < $n; $i++) {
                $c = $s[$i];
                if ($min === null || $c < $min) {
                    $min = $c;
                    $cnt = 1;
                } elseif ($c === $min) {
                    $cnt++;
                }
            }
            return $cnt;
        };
        // counts of words by frequency value (max length 10 => freq 1..10, but be safe up to 11)
        $bucket = array_fill(0, 12, 0);
        foreach ($words as $w) {
            $v = $f($w);
            if ($v > 11) $v = 11;
            $bucket[$v]++;
        }
        // suffix sums: greater[k] = number of words with f > k
        $greater = array_fill(0, 13, 0);
        for ($k = 11; $k >= 0; $k--) {
            $greater[$k] = $greater[$k + 1] + $bucket[$k];
        }
        $ans = [];
        foreach ($queries as $q) {
            $v = $f($q);
            if ($v >= 11) {
                $ans[] = 0;
            } else {
                $ans[] = $greater[$v + 1];
            }
        }
        return $ans;
    }
}
