    function countMaxOrSubsets($nums) {
        $n = count($nums);
        $maxOr = 0;
        foreach ($nums as $v) {
            $maxOr |= $v;
        }
        $total = 1 << $n;
        $dp = array_fill(0, $total, 0);
        $count = 0;
        for ($mask = 1; $mask < $total; $mask++) {
            $low = $mask & (-$mask);
            $idx = (int)log($low, 2);
            // safer bit index computation
            $idx = 0;
            $tmp = $low;
            while ($tmp > 1) {
                $tmp >>= 1;
                $idx++;
