    function eventualSafeNodes($graph) {
        $n = count($graph);
        $outdeg = array_fill(0, $n, 0);
        $rev = array_fill(0, $n, []);
        for ($i = 0; $i < $n; $i++) {
            $outdeg[$i] = count($graph[$i]);
            foreach ($graph[$i] as $j) {
                $rev[$j][] = $i;
            }
        }
        $queue = [];
        $safe = array_fill(0, $n, false);
        for ($i = 0; $i < $n; $i++) {
            if ($outdeg[$i] == 0) {
                $queue[] = $i;
                $safe[$i] = true;
            }
        }
        $head = 0;
        while ($head < count($queue)) {
            $node = $queue[$head++];
            foreach ($rev[$node] as $p) {
                $outdeg[$p]--;
