        $this->k = $k;
        $this->cnt = array_fill(0, $this->N + 1, 0);
        $this->sm = array_fill(0, $this->N + 1, 0);
        $this->queue = [];
        $this->head = 0;
        $this->size = 0;
        $this->total = 0;
    }

    private function update($i, $dc, $ds) {
        $N = $this->N;
        while ($i <= $N) {
            $this->cnt[$i] += $dc;
            $this->sm[$i] += $ds;
            $i += $i & (-$i);
        }
    }

    // sum of the smallest $k elements currently in the window
    private function smallestSum($k) {
        if ($k <= 0) return 0;
        $pos = 0;
        $remaining = $k;
        $sum = 0;
        for ($bit = 65536; $bit > 0; $bit >>= 1) {
            $next = $pos + $bit;
            if ($next <= $this->N && $this->cnt[$next] < $remaining) {
                $remaining -= $this->cnt[$next];
                $sum += $this->sm[$next];
                $pos = $next;
            }
        }
        return $sum + $remaining * ($pos + 1);
    }

