        $this->queue[] = $num;
        $this->size++;
        $this->total += $num;
        $this->update($num, 1, $num);
        if ($this->size > $this->m) {
            $old = $this->queue[$this->head];
            unset($this->queue[$this->head]);
            $this->head++;
            $this->size--;
            $this->total -= $old;
            $this->update($old, -1, -$old);
        }
    }

