class Solution {

    /**
     * @param Integer[][] $students
     * @param Integer[][] $mentors
     * @return Integer
     */
    function maxCompatibilitySum($students, $mentors) {
        $m = count($students);
        $n = count($students[0]);
        $score = array_fill(0, $m, array_fill(0, $m, 0));
        for ($i = 0; $i < $m; $i++) {
            for ($j = 0; $j < $m; $j++) {
                $s = 0;
                for ($k = 0; $k < $n; $k++) {
                    if ($students[$i][$k] == $mentors[$j][$k]) {
                        $s++;
                    }
                }
                $score[$i][$j] = $s;
            }
        }
        $full = 1 << $m;
        $dp = array_fill(0, $full, -1);
        $dp[0] = 0;
        for ($mask = 0; $mask < $full; $mask++) {
            if ($dp[$mask] < 0) continue;
            $i = 0;
            $t = $mask;
            while ($t) {
                $i += $t & 1;
                $t >>= 1;
            }
            if ($i >= $m) continue;
            for ($j = 0; $j < $m; $j++) {
                if (($mask >> $j) & 1) continue;
                $nm = $mask | (1 << $j);
                $val = $dp[$mask] + $score[$i][$j];
                if ($val > $dp[$nm]) {
                    $dp[$nm] = $val;
                }
            }
        }
        return $dp[$full - 1];
    }
}
