```php
class Solution {

    /**
     * @param Integer[][] $fruits
     * @param Integer $startPos
     * @param Integer $k
     * @return Integer
     */
    function maxTotalFruits($fruits, $startPos, $k) {
        $n = count($fruits);
        $best = 0;
        $sum = 0;
        $i = 0;
        for ($j = 0; $j < $n; $j++) {
            $sum += $fruits[$j][1];
            while ($i <= $j) {
                $L = $fruits[$i][0];
                $R = $fruits[$j][0];
                $len = $R - $L;
                $cost = $len + min(abs($startPos - $L), abs($startPos - $R));
                if ($cost <= $k) {
                    break;
                }
                $sum -= $fruits[$i][1];
                $i++;
            }
            if ($i <= $j && $sum > $best) {
                $best = $sum;
            }
        }
        return $best;
    }
}
