class Solution {

    /**
     * @param Integer $n
     * @param Integer[] $batteries
     * @return Integer
     */
    function maxRunTime($n, $batteries) {
        $total = 0;
        foreach ($batteries as $b) {
            $total += $b;
        }
        $lo = 1;
        $hi = intdiv($total, $n);
        while ($lo < $hi) {
            $mid = $lo + intdiv($hi - $lo + 1, 2);
            $sum = 0;
            foreach ($batteries as $b) {
                $sum += ($b < $mid) ? $b : $mid;
            }
            if ($sum >= $n * $mid) {
                $lo = $mid;
            } else {
                $hi = $mid - 1;
            }
        }
        return $lo;
    }
}
