class Solution {

    /**
     * @param String[][] $seats
     * @return Integer
     */
    function maxStudents($seats) {
        $m = count($seats);
        $n = count($seats[0]);
        $full = 1 << $n;

        // available mask per row
        $avail = [];
        for ($i = 0; $i < $m; $i++) {
            $mask = 0;
            for ($j = 0; $j < $n; $j++) {
                if (trim($seats[$i][$j]) === '.') {
                    $mask |= (1 << $j);
                }
            }
            $avail[$i] = $mask;
        }

        // popcount helper
        $popcount = function ($x) {
            $c = 0;
            while ($x) {
                $x &= $x - 1;
                $c++;
            }
            return $c;
        };

        // valid row masks per row
        $validMasks = [];
        for ($i = 0; $i < $m; $i++) {
            $validMasks[$i] = [];
            for ($mask = 0; $mask < $full; $mask++) {
                if (($mask & $avail[$i]) !== $mask) continue;
                if ($mask & ($mask << 1)) continue;
                $validMasks[$i][] = $mask;
            }
        }

        $prev = array_fill(0, $full, -1);
        $prev[0] = 0;

        for ($i = 0; $i < $m; $i++) {
            $cur = array_fill(0, $full, -1);
            foreach ($validMasks[$i] as $mask) {
                $cnt = $popcount($mask);
                for ($pm = 0; $pm < $full; $pm++) {
                    if ($prev[$pm] < 0) continue;
                    if ($mask & ($pm << 1)) continue;
                    if ($mask & ($pm >> 1)) continue;
                    $val = $prev[$pm] + $cnt;
                    if ($val > $cur[$mask]) {
                        $cur[$mask] = $val;
                    }
                }
            }
            $prev = $cur;
        }

        $best = 0;
        foreach ($prev as $v) {
            if ($v > $best) $best = $v;
        }
        return $best;
    }
}
