    /**
     * @param Integer[] $nums
     * @param Integer $firstLen
     * @param Integer $secondLen
     * @return Integer
     */
    function maxSumTwoNoOverlap($nums, $firstLen, $secondLen) {
        $n = count($nums);
        $prefix = array_fill(0, $n + 1, 0);
        for ($i = 0; $i < $n; $i++) {
            $prefix[$i + 1] = $prefix[$i] + $nums[$i];
        }
        return max(
            $this->helper($prefix, $n, $firstLen, $secondLen),
            $this->helper($prefix, $n, $secondLen, $firstLen)
        );
    }

    private function helper($prefix, $n, $L, $M) {
        // L-length subarray before M-length subarray
        $best = 0;
        $maxL = 0;
        for ($i = $L + $M; $i <= $n; $i++) {
            // L subarray ends at i - M
            $sumL = $prefix[$i - $M] - $prefix[$i - $M - $L];
            if ($sumL > $maxL) {
                $maxL = $sumL;
            }
            $sumM = $prefix[$i] - $prefix[$i - $M];
            $total = $maxL + $sumM;
            if ($total > $best) {
                $best = $total;
            }
        }
        return $best;
    }
}
