```php
class Solution {

    /**
     * @param Integer[][] $graph
     * @param Integer[] $initial
     * @return Integer
     */
    function minMalwareSpread($graph, $initial) {
        $n = count($graph);
        $adj = [];
        for ($i = 0; $i < $n; $i++) {
            $adj[$i] = [];
            for ($j = 0; $j < $n; $j++) {
                if ($i != $j && $graph[$i][$j] == 1) {
                    $adj[$i][] = $j;
                }
            }
        }
        sort($initial);
        $best = -1;
        $bestCount = PHP_INT_MAX;
        foreach ($initial as $removed) {
            $visited = array_fill(0, $n, false);
            $visited[$removed] = true;
            $queue = [];
            $head = 0;
            foreach ($initial as $s) {
                if ($s == $removed) continue;
                if (!$visited[$s]) {
                    $visited[$s] = true;
                    $queue[] = $s;
                }
            }
            $count = count($queue);
            while ($head < count($queue)) {
                $u = $queue[$head++];
                foreach ($adj[$u] as $v) {
                    if (!$visited[$v]) {
                        $visited[$v] = true;
                        $queue[] = $v;
                        $count++;
                    }
                }
            }
            if ($count < $bestCount) {
                $bestCount = $count;
                $best = $removed;
            }
        }
        return $best;
    }
}
