class Solution {

    /**
     * @param TreeNode $root
     * @return Integer
     */
    function minDepth($root) {
        if ($root === null) {
            return 0;
        }
        $queue = [$root];
        $head = 0;
        $depth = 1;
        while ($head < count($queue)) {
            $levelEnd = count($queue);
            for (; $head < $levelEnd; $head++) {
                $node = $queue[$head];
                if ($node->left === null && $node->right === null) {
                    return $depth;
