```php
class Solution {

    /**
     * @param Integer[] $tasks
     * @param Integer $sessionTime
     * @return Integer
     */
    function minSessions($tasks, $sessionTime) {
        $n = count($tasks);
        $full = (1 << $n) - 1;
        $INF = PHP_INT_MAX;
        // dp[mask] = sessions * 16 + usedInLastSession (minimized)
        $dp = array_fill(0, $full + 1, $INF);
        $dp[0] = 0;
        for ($mask = 0; $mask <= $full; $mask++) {
            if ($dp[$mask] === $INF) continue;
            $sessions = intdiv($dp[$mask], 16);
            $used = $dp[$mask] % 16;
            for ($i = 0; $i < $n; $i++) {
                if ($mask & (1 << $i)) continue;
                $nm = $mask | (1 << $i);
                if ($used + $tasks[$i] <= $sessionTime) {
                    $val = $sessions * 16 + $used + $tasks[$i];
                } else {
                    $val = ($sessions + 1) * 16 + $tasks[$i];
                }
                if ($val < $dp[$nm]) $dp[$nm] = $val;
            }
        }
        $res = $dp[$full];
        $sessions = intdiv($res, 16);
        $used = $res % 16;
        return $used > 0 ? $sessions + 1 : $sessions;
    }
}
