```php
class Solution {

    /**
     * @param String $date1
     * @param String $date2
     * @return Integer
     */
    function daysBetweenDates($date1, $date2) {
        return abs($this->toDays($date1) - $this->toDays($date2));
    }

    private function isLeap($y) {
        return ($y % 4 == 0 && $y % 100 != 0) || ($y % 400 == 0);
    }

    private function toDays($date) {
        $parts = explode('-', $date);
        $y = (int)$parts[0];
        $m = (int)$parts[1];
        $d = (int)$parts[2];
        $monthDays = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
        $days = 0;
        for ($year = 1971; $year < $y; $year++) {
            $days += $this->isLeap($year) ? 366 : 365;
        }
        for ($month = 1; $month < $m; $month++) {
            $days += $monthDays[$month - 1];
            if ($month == 2 && $this->isLeap($y)) {
                $days += 1;
            }
        }
        $days += $d;
        return $days;
    }
}
