Classic: choose n non-adjacent elements from a circular array of 3n elements maximizing sum. Solve linear version twice (excluding first or last element).

```php
class Solution {

    /**
     * @param Integer[] $slices
     * @return Integer
     */
    function maxSizeSlices($slices) {
        $m = count($slices);
        $n = intdiv($m, 3);
        $a = array_slice($slices, 1);
        $b = array_slice($slices, 0, $m - 1);
        return max($this->solve($a, $n), $this->solve($b, $n));
    }

    private function solve($arr, $n) {
        $len = count($arr);
        $NEG = -1000000000;
        // dp[i][j]: max sum using first i elements picking j non-adjacent
        $prev2 = array_fill(0, $n + 1, $NEG); // dp[i-2]
        $prev1 = array_fill(0, $n + 1, $NEG); // dp[i-1]
        $prev2[0] = 0;
        $prev1[0] = 0;
        if ($len >= 1) {
            $prev1[1] = $arr[0];
        }
        for ($i = 2; $i <= $len; $i++) {
            $cur = array_fill(0, $n + 1, $NEG);
            $cur[0] = 0;
            for ($j = 1; $j <= $n; $j++) {
                $take = $prev2[$j - 1] > $NEG ? $prev2[$j - 1] + $arr[$i - 1] : $NEG;
                $cur[$j] = max($prev1[$j], $take);
            }
            $prev2 = $prev1;
            $prev1 = $cur;
        }
        return $prev1[$n];
    }
}
