class Solution {

    /**
     * @param String[] $grid
     * @return Integer
     */
    function regionsBySlashes($grid) {
        $n = count($grid);
        $size = $n * $n * 4;
        $parent = range(0, $size - 1);
        $count = $size;

        $find = function($x) use (&$parent, &$find) {
            while ($parent[$x] != $x) {
                $parent[$x] = $parent[$parent[$x]];
                $x = $parent[$x];
            }
            return $x;
        };

        $union = function($a, $b) use (&$parent, &$count, &$find) {
            $ra = $find($a);
            $rb = $find($b);
            if ($ra != $rb) {
                $parent[$ra] = $rb;
                $count--;
            }
        };

        for ($i = 0; $i < $n; $i++) {
            for ($j = 0; $j < $n; $j++) {
                $base = ($i * $n + $j) * 4;
                $c = $grid[$i][$j];
                if ($c == '/') {
                    $union($base + 0, $base + 3);
                    $union($base + 1, $base + 2);
                } elseif ($c == '\\') {
                    $union($base + 0, $base + 1);
                    $union($base + 2, $base + 3);
                } else {
                    $union($base + 0, $base + 1);
                    $union($base + 1, $base + 2);
                    $union($base + 2, $base + 3);
                }
                // connect to right neighbor
                if ($j + 1 < $n) {
                    $right = ($i * $n + $j + 1) * 4;
                    $union($base + 1, $right + 3);
                }
                // connect to bottom neighbor
                if ($i + 1 < $n) {
                    $down = (($i + 1) * $n + $j) * 4;
                    $union($base + 2, $down + 0);
                }
            }
        }

        return $count;
    }
}
