class Solution {

    /**
     * @param String $s
     * @return String[]
     */
    function removeInvalidParentheses($s) {
        $n = strlen($s);
        $removeLeft = 0;
        $removeRight = 0;
        for ($i = 0; $i < $n; $i++) {
            $c = $s[$i];
            if ($c === '(') {
                $removeLeft++;
            } elseif ($c === ')') {
                if ($removeLeft > 0) {
                    $removeLeft--;
                } else {
                    $removeRight++;
                }
            }
        }
        $result = [];
        $this->dfs($s, 0, $n, 0, $removeLeft, $removeRight, '', $result);
        return array_keys($result);
    }

    private function dfs($s, $idx, $n, $balance, $rl, $rr, $cur, &$result) {
        if ($balance < 0 || $rl < 0 || $rr < 0) {
            return;
        }
        if ($idx === $n) {
            if ($balance === 0 && $rl === 0 && $rr === 0) {
                $result[$cur] = true;
            }
            return;
        }
        $c = $s[$idx];
        if ($c === '(') {
            // remove it
            if ($rl > 0) {
                $this->dfs($s, $idx + 1, $n, $balance, $rl - 1, $rr, $cur, $result);
            }
            // keep it
            $this->dfs($s, $idx + 1, $n, $balance + 1, $rl, $rr, $cur . $c, $result);
        } elseif ($c === ')') {
            // remove it
            if ($rr > 0) {
                $this->dfs($s, $idx + 1, $n, $balance, $rl, $rr - 1, $cur, $result);
            }
