class Solution {

    /**
     * @param Integer[][] $adjacentPairs
     * @return Integer[]
     */
    function restoreArray($adjacentPairs) {
        $adj = [];
        foreach ($adjacentPairs as $p) {
            $u = $p[0];
            $v = $p[1];
            if (!isset($adj[$u])) $adj[$u] = [];
            if (!isset($adj[$v])) $adj[$v] = [];
            $adj[$u][] = $v;
            $adj[$v][] = $u;
        }
        $start = null;
        foreach ($adj as $node => $neighbors) {
            if (count($neighbors) === 1) {
                $start = $node;
                break;
            }
        }
        $n = count($adjacentPairs) + 1;
        $result = [];
        $prev = null;
        $cur = $start;
        for ($i = 0; $i < $n; $i++) {
            $result[] = $cur;
            $next = null;
            foreach ($adj[$cur] as $nb) {
                if ($prev === null || $nb !== $prev) {
                    $next = $nb;
                    break;
                }
            }
            $prev = $cur;
            $cur = $next;
            if ($cur === null) break;
        }
        return $result;
    }
}
