Sort products, then for each prefix filter progressively (only products matching the previous prefix can match the current one), taking the first three.

```php
class Solution {

    /**
     * @param String[] $products
     * @param String $searchWord
     * @return String[][]
     */
    function suggestedProducts($products, $searchWord) {
        sort($products, SORT_STRING);
        $result = [];
        $candidates = $products;
        $len = strlen($searchWord);
        for ($i = 0; $i < $len; $i++) {
            $ch = $searchWord[$i];
            $next = [];
            foreach ($candidates as $p) {
                if (strlen($p) > $i && $p[$i] === $ch) {
                    $next[] = $p;
                }
            }
            $candidates = $next;
            $result[] = array_slice($candidates, 0, 3);
        }
        return $result;
    }
}
