class Solution {

    /**
     * @param Integer[] $nums
     * @param Integer $k
     * @return Float[]
     */
    function medianSlidingWindow($nums, $k) {
        $n = count($nums);
        $sorted = array_values(array_unique($nums));
        sort($sorted);
        $m = count($sorted);
        $index = array();
        foreach ($sorted as $i => $v) {
            $index[$v] = $i + 1;
        }
        $tree = array_fill(0, $m + 1, 0);
        $LOG = 1;
        while (($LOG << 1) <= $m) {
            $LOG <<= 1;
        }

        $update = function ($i, $delta) use (&$tree, $m) {
            for (; $i <= $m; $i += $i & (-$i)) {
                $tree[$i] += $delta;
            }
        };

        $kth = function ($r) use (&$tree, $m, $LOG, $sorted) {
            $pos = 0;
            $rem = $r;
            for ($pw = $LOG; $pw > 0; $pw >>= 1) {
                $np = $pos + $pw;
                if ($np <= $m && $tree[$np] < $rem) {
                    $pos = $np;
                    $rem -= $tree[$np];
                }
            }
            return $sorted[$pos];
        };

        $result = array();
        $odd = ($k % 2 === 1);
        $half = intdiv($k, 2);

        for ($i = 0; $i < $n; $i++) {
            $update($index[$nums[$i]], 1);
            if ($i >= $k) {
                $update($index[$nums[$i - $k]], -1);
            }
            if ($i >= $k - 1) {
                if ($odd) {
                    $result[] = (float)$kth($half + 1);
                } else {
                    $a = $kth($half);
                    $b = $kth($half + 1);
                    $result[] = ($a + $b) / 2.0;
                }
            }
        }
        return $result;
    }
}
