class Solution {

    /**
     * @param Integer[] $nums
     * @param Integer $k
     * @return Integer
     */
    function splitArray($nums, $k) {
        $lo = 0;
        $hi = 0;
        foreach ($nums as $v) {
            $hi += $v;
            if ($v > $lo) {
                $lo = $v;
            }
        }
        while ($lo < $hi) {
            $mid = intdiv($lo + $hi, 2);
            $count = 1;
            $cur = 0;
            foreach ($nums as $v) {
                if ($cur + $v > $mid) {
                    $count++;
                    $cur = $v;
                } else {
                    $cur += $v;
                }
            }
            if ($count <= $k) {
                $hi = $mid;
            } else {
                $lo = $mid + 1;
            }
        }
        return $lo;
    }
}
