```php
class StreamChecker {
    private $trie;
    private $buf;
    private $maxLen;

    /**
     * @param String[] $words
     */
    function __construct($words) {
        $this->trie = [];
        $this->buf = [];
        $this->maxLen = 0;
        foreach ($words as $w) {
            $n = strlen($w);
            if ($n > $this->maxLen) $this->maxLen = $n;
            $node = &$this->trie;
            for ($i = $n - 1; $i >= 0; $i--) {
                $c = $w[$i];
                if (!isset($node[$c])) {
                    $node[$c] = [];
                }
                $node = &$node[$c];
            }
            $node['$'] = true;
            unset($node);
        }
    }

    /**
     * @param String $letter
     * @return Boolean
     */
    function query($letter) {
        $this->buf[] = $letter;
        if (count($this->buf) > $this->maxLen) {
            array_shift($this->buf);
        }
        $node = $this->trie;
        for ($i = count($this->buf) - 1; $i >= 0; $i--) {
            $c = $this->buf[$i];
            if (!isset($node[$c])) {
                return false;
            }
            $node = $node[$c];
            if (isset($node['$'])) {
                return true;
            }
        }
        return false;
    }
}

