    function earliestAndLatest($n, $firstPlayer, $secondPlayer) {
        $this->memo = [];
        return $this->dp($n, $firstPlayer, $secondPlayer);
    }

    private function dp($n, $f, $s) {
        if ($f + $s == $n + 1) {
            return [1, 1];
        }
        if ($f + $s > $n + 1) {
            $nf = $n + 1 - $s;
            $ns = $n + 1 - $f;
            $f = $nf;
            $s = $ns;
        }
        $key = $n . ',' . $f . ',' . $s;
        if (isset($this->memo[$key])) {
            return $this->memo[$key];
        }
        $half = intdiv($n + 1, 2);
        $earliest = PHP_INT_MAX;
        $latest = PHP_INT_MIN;
        if ($s <= $half) {
            for ($i = 0; $i < $f; $i++) {
                for ($j = 0; $j < $s - $f; $j++) {
                    $res = $this->dp($half, $i + 1, $i + $j + 2);
                    if ($res[0] < $earliest) $earliest = $res[0];
                    if ($res[1] > $latest) $latest = $res[1];
