    /**
     * @param String $beginWord
     * @param String $endWord
     * @param String[] $wordList
     * @return Integer
     */
    function ladderLength($beginWord, $endWord, $wordList) {
        $dict = array_flip($wordList);
        if (!isset($dict[$endWord])) {
            return 0;
        }
        $len = strlen($beginWord);
        $queue = [$beginWord];
        $visited = [$beginWord => true];
        $steps = 1;
        while (!empty($queue)) {
            $next = [];
            foreach ($queue as $word) {
                if ($word === $endWord) {
                    return $steps;
                }
                for ($i = 0; $i < $len; $i++) {
                    $orig = $word[$i];
                    for ($c = 97; $c <= 122; $c++) {
                        $ch = chr($c);
                        if ($ch === $orig) continue;
                        $word[$i] = $ch;
                        if (isset($dict[$word]) && !isset($visited[$word])) {
                            $visited[$word] = true;
                            $next[] = $word;
                        }
                    }
                    $word[$i] = $orig;
                }
            }
            $queue = $next;
            $steps++;
        }
        return 0;
    }
}
